// Transform wttr.in response to CanonicalWeather format
try {
  const webhookData = $node['Webhook Trigger'].json?.body ?? {};
  const weatherData = $node['Get Weather'].json ?? {};

  // Check for API errors
  if (weatherData.error || !weatherData.current_condition || weatherData.current_condition.length === 0) {
    return [{
      json: {
        status: 'error',
        error: weatherData.error ?? `City not found or API error: ${webhookData.city ?? 'unknown'}`,
        meta: {
          provider: 'wttr',
          timestamp: new Date().toISOString(),
          requestedCity: webhookData.city ?? 'unknown'
        }
      }
    }];
  }

  // Check for location data
  if (!weatherData.nearest_area || weatherData.nearest_area.length === 0) {
    return [{
      json: {
        status: 'error',
        error: 'Location data not available',
        meta: {
          provider: 'wttr',
          timestamp: new Date().toISOString(),
          requestedCity: webhookData.city ?? 'unknown'
        }
      }
    }];
  }

  const current = weatherData.current_condition[0];
  const area = weatherData.nearest_area[0];

  // Build canonical response
  const canonical = {
    location: {
      city: area.areaName?.[0]?.value ?? 'Unknown',
      country: area.country?.[0]?.value ?? 'Unknown',
      latitude: parseFloat(area.latitude),
      longitude: parseFloat(area.longitude)
    },
    current: {
      temperature: parseFloat(current.temp_C),
      feelsLike: parseFloat(current.FeelsLikeC),
      humidity: parseFloat(current.humidity),
      windSpeed: parseFloat(current.windspeedKmph),
      windDirection: parseFloat(current.winddirDegree),
      weatherCode: parseInt(current.weatherCode),
      pressure: parseFloat(current.pressure)
    },
    meta: {
      provider: 'wttr',
      timestamp: new Date().toISOString(),
      requestedCity: webhookData.city ?? 'unknown'
    },
    status: 'success'
  };

  return [{ json: canonical }];
} catch (error) {
  return [{
    json: {
      status: 'error',
      error: error.message,
      meta: {
        provider: 'wttr',
        timestamp: new Date().toISOString(),
        requestedCity: 'unknown'
      }
    }
  }];
}
